PREFIX energia: <https://w3id.org/rastro/energia#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT (COUNT(DISTINCT ?p) AS ?n) WHERE {
  ?run a energia:ModelRun ; energia:current true .
  ?p a energia:Prediction ; prov:wasGeneratedBy ?run ; energia:inTest true ; prov:used ?s .
  ?s a energia:Stake ; energia:partner ?co .
  {
    ?s energia:rule ?r .
    FILTER(CONTAINS(LCASE(STR(?r)), "revisada"))
  } UNION {
    ?cn a energia:CompanyName ; energia:company ?co ; energia:rule ?r .
    FILTER(CONTAINS(LCASE(STR(?r)), "revisada"))
  }
}

PREFIX energia: <https://w3id.org/rastro/energia#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT (COUNT(DISTINCT ?p) AS ?n) WHERE {
  ?p a energia:Prediction ;
     energia:inTest true ;
     prov:wasGeneratedBy ?run .
  ?run a energia:ModelRun ;
       energia:current true .
  {
    ?p prov:used ?s .
    ?s a energia:Stake ;
       energia:rule ?r .
    FILTER(CONTAINS(LCASE(STR(?r)), "revisada"))
  }
  UNION
  {
    ?p prov:used ?ws .
    ?ws a energia:WellStart ;
        energia:company ?c ;
        energia:declaredName ?dn .
    ?cn a energia:CompanyName ;
        energia:company ?c ;
        energia:nameInSource ?dn ;
        energia:rule ?r2 .
    FILTER(CONTAINS(LCASE(STR(?r2)), "revisada"))
  }
}

PREFIX energia: <https://w3id.org/rastro/energia#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT (COUNT(DISTINCT ?p) AS ?n) WHERE {
  {
    SELECT ?p ?sm (MAX(?ld) AS ?lastLoaded) WHERE {
      ?run a energia:ModelRun ; energia:current true .
      ?p a energia:Prediction ; prov:wasGeneratedBy ?run ; energia:inTest true ; prov:used ?f , ?ws .
      ?f a energia:Fracturing ; prov:wasDerivedFrom ?rep .
      ?rep a energia:FractureReport ; energia:loadedOn ?ld .
      ?ws a energia:WellStart ; energia:startMonth ?sm .
    }
    GROUP BY ?p ?sm
  }
  FILTER((YEAR(?lastLoaded) * 12 + MONTH(?lastLoaded)) > (YEAR(?sm) * 12 + MONTH(?sm)))
}
